namespace AerialWatch.Domain.Wfp.ResearchModel;

/// <summary>
/// One coefficient the research model uses (table wfp.CoefficientTypes), e.g. "thermal camera, time + season model,
/// intercept". Reference data: seeded by migration, never edited by the app. Saved values point at it by Id.
/// </summary>
public class CoefficientType
{
    public const int CodeMaxLength = 60;
    public const int LabelMaxLength = 60;
    public const int DescriptionMaxLength = 200;

    /// <summary>Fixed id, set by the seed migration (not generated by SQL).</summary>
    public int Id { get; set; }

    /// <summary>Stable key used by the API and the admin page, e.g. "thermal.timeSeason.intercept".</summary>
    public string Code { get; set; } = string.Empty;

    public CameraType Camera { get; set; }
    public DetectionModelKind Model { get; set; }
    public CoefficientTerm Term { get; set; }

    public string Label { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;

    /// <summary>Display order on the admin page.</summary>
    public int SortOrder { get; set; }

    public static string CodeFor(CameraType camera, DetectionModelKind model, CoefficientTerm term) =>
        $"{Camel(camera.ToString())}.{Camel(model.ToString())}.{Camel(term.ToString())}";

    private static string Camel(string s) => char.ToLowerInvariant(s[0]) + s[1..];
}
